// Pre-recorded Stavebien audio lives in public/spill/stavebien/lyd/<id>-<del>.mp3.
// Generated by scripts/spill/lag-stavelyd.py with the open Kokoro-82M model (American English, af_heart).
// scripts/spill/lag-stavelyd-liste.mjs reads this file, so ids and spoken text stay in sync with the site.

export const LYD_MAPPE = "/spill/stavebien/lyd"

export type LydDel = "ord" | "definisjon" | "setning"
export const LYD_DELER: Record<LydDel, string> = { ord: "o", definisjon: "d", setning: "s" }

/** Stable, non-revealing file id for a word (FNV-1a, 32 bit). */
export function lydId(ord: string) {
  let h = 0x811c9dc5
  for (const tegn of ord.normalize("NFC")) {
    h ^= tegn.codePointAt(0)!
    h = Math.imul(h, 0x01000193) >>> 0
  }
  return h.toString(36).padStart(7, "0")
}

/** What the voice reads for each part. The example sentence is read with the word filled in. */
export function lydTekst(o: { word: string; definition: string; sentence: string }, del: LydDel) {
  if (del === "ord") return o.word
  if (del === "definisjon") return o.definition
  return o.sentence.replaceAll("___", o.word)
}
